'use strict';
const $ = s => document.querySelector(s);
const esc = value => String(value ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const normalize = value => String(value ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const templates = [
 {id:'general',name:'通用教授档案',en:'General faculty',description:'一份清晰完整的基础人事档案。',items:['个人信息与联络方式','任职信息与聘期','教育背景与工作经历'],extra:[['education','教育背景 / Education','textarea'],['experience','工作经历 / Experience','textarea']]},
 {id:'academic',name:'教学科研档案',en:'Teaching & research',description:'完整记录学术方向与教学成果。',items:['通用人事信息','研究方向、课程与指导','论文、项目与学术荣誉'],extra:[['education','教育背景 / Education','textarea'],['research','研究方向 / Research interests','textarea'],['courses','授课与学生指导 / Teaching','textarea'],['publications','论文与代表成果 / Publications','textarea'],['grants','科研项目 / Grants','textarea'],['awards','荣誉与奖项 / Awards','textarea']]},
 {id:'international',name:'国际／访问学者档案',en:'International & visiting',description:'为跨国聘任和学术交流整理材料。',items:['双语身份与所属机构','访问安排与校内联系人','工作许可、签证有效日期'],extra:[['homeInstitution','原属机构 / Home institution','text'],['host','校内联系人 / Host contact','text'],['visitStart','访问开始 / Visit starts','date'],['visitEnd','访问结束 / Visit ends','date'],['permitExpiry','工作许可有效期 / Work permit expiry','date'],['visaExpiry','签证有效期 / Visa expiry','date'],['language','工作语言 / Working languages','text'],['visitPurpose','访问目的 / Visit purpose','textarea']]}
];
const baseFields = [
 ['name','姓名 / Full name','text',true],['englishName','英文名 / English name','text'],['sortName','排序名（拼音或拉丁字母）/ Sort name','text',true],['employeeId','教职工编号 / Employee ID','text'],['department','院系 / Department','text',true],['title','职称 / Title','text'],['status','任职状态 / Status','select',false,['在职','访问中','待入职','已离职']],['category','学者类别 / Category','select',false,['本国学者','国际学者']],['email','工作邮箱 / Email','email'],['phone','联系电话 / Phone','tel'],['nationality','国籍 / Nationality','text'],['startDate','入职日期 / Start date','date'],['contractEnd','聘期结束 / Contract ends','date'],['source','材料来源 / Source reference','text'],['notes','人事备注 / HR notes','textarea']
];
let demo=false, session=null, role='viewer', records=[], editing=null, custom=[], letter='全部', syncTimer=null, refreshing=null, epoch=0, busy=false, dirty=false;
let demoFiles=new Map();
const config=window.FACULTY_CONFIG||{};
const configured= /^https:\/\/[a-z0-9-]+\.supabase\.co\/?$/i.test(config.supabaseUrl||'') && !!config.supabaseKey && !config.supabaseKey.startsWith('sb_secret_');
const baseUrl=(config.supabaseUrl||'').replace(/\/$/,'');
const writable=()=>demo||role==='editor';
function toast(text){$('#toast').textContent=text;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').textContent='',4500)}
function friendly(e){if(e.name==='TimeoutError')return '请求超时。请保留表单并同步检查保存状态，不要重复创建档案。';if(e.message==='Failed to fetch')return '网络连接失败，请检查网络后重试；表单内容仍保留。';return e.message||'操作失败，请重试。'}
async function request(path,{method='GET',body,headers={},anonymous=false,blob=false}={}){
 if(!configured)throw Error('尚未接入 Supabase，请按部署说明配置项目。');
 const response=await fetch(baseUrl+path,{method,headers:{apikey:config.supabaseKey,...(!anonymous&&session?{Authorization:'Bearer '+session.access_token}:{}),...(body!==undefined&&!(body instanceof File)?{'Content-Type':'application/json'}:{}),...headers},body:body===undefined?undefined:body instanceof File?body:JSON.stringify(body),cache:'no-store',signal:AbortSignal.timeout(20000)});
 if(!response.ok){const problem=await response.json().catch(()=>({}));if(response.status===401)throw Error('登录已过期或账号密码不正确，请重新登录。');if(response.status===403)throw Error('没有操作权限，请联系管理员。');throw Error(problem.message||problem.msg||problem.error_description||problem.error||'请求失败（'+response.status+'）');}
 if(blob)return response.blob();
 if(response.status===204)return null;
 const text=await response.text();return text?JSON.parse(text):null;
}
async function ensureSession(){
 if(demo)return;
 if(!session)throw Error('请先登录。');
 if(session.expires_at>Date.now()/1000+60)return;
 if(!refreshing)refreshing=request('/auth/v1/token?grant_type=refresh_token',{method:'POST',body:{refresh_token:session.refresh_token},anonymous:true}).then(data=>{session={...data,expires_at:Date.now()/1000+data.expires_in}}).finally(()=>refreshing=null);
 await refreshing;
}
function sampleRecords(){const names=[['陈知远','Zhiyuan Chen','Chen Zhiyuan','人文学院','教授','general','在职','本国学者'],['Elena Rossi','','Rossi Elena','建筑与设计学院','访问教授','international','访问中','国际学者'],['林若宁','Ruoning Lin','Lin Ruoning','信息工程学院','副教授','academic','在职','本国学者'],['James Wilson','','Wilson James','经济管理学院','教授','academic','在职','国际学者'],['王书言','Shuyan Wang','Wang Shuyan','人文学院','教授','general','在职','本国学者'],['张明远','Mingyuan Zhang','Zhang Mingyuan','信息工程学院','讲席教授','academic','待入职','本国学者']];return names.map((n,i)=>({id:crypto.randomUUID(),template:n[5],version:1,updated_at:new Date(Date.now()-i*86400000).toISOString(),data:{name:n[0],englishName:n[1],sortName:n[2],department:n[3],title:n[4],status:n[6],category:n[7],employeeId:'DEMO-00'+(i+1),email:'faculty'+(i+1)+'@example.edu',source:'虚构演示材料',notes:'此记录为虚构演示内容，不代表真实教授。',custom:[]}}))}
async function enter(){
 $('#login').hidden=true;$('#workspace').hidden=false;$('#new-record').hidden=!writable();
 $('#account-name').textContent=demo?'演示工作台':session.user.email;$('#account-role').textContent=demo?'本次页面 · 虚构数据':role==='editor'?'HR 编辑成员':'HR 只读成员';$('#connection').textContent=demo?'演示模式 · 虚构数据':'已连接 · 团队档案';
 if(demo)records=sampleRecords();render();setView('all');if(!demo){await refresh();syncTimer=setInterval(()=>{if(!busy)refresh().catch(()=>{$('#connection').textContent='同步失败 · 请重试'})},30000)}
}
async function refresh(){if(demo){render();toast('演示模式，无云端数据');return}await ensureSession();const current=epoch;let all=[];for(let offset=0;;offset+=1000){const rows=await request('/rest/v1/profiles?select=*&order=id.asc&limit=1000&offset='+offset);all.push(...rows);if(rows.length<1000)break;}if(current!==epoch||!session)return;records=all;render();$('#connection').textContent='已连接 · 团队档案';$('#sync-time').textContent='最近同步 '+new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'})}
function filteredRecords(){const q=normalize($('#search').value.trim());return records.filter(r=>{const d=r.data;return (!q||normalize([d.name,d.englishName,d.sortName,d.department,d.employeeId].join(' ')).includes(q))&&(!$('#department').value||d.department===$('#department').value)&&(!$('#status').value||d.status===$('#status').value)&&(letter==='全部'||(normalize(d.sortName).charAt(0).toUpperCase().match(/[A-Z]/)?.[0]||'#')===letter)}).sort((a,b)=>a.data.sortName.localeCompare(b.data.sortName,'en',{sensitivity:'base'})||a.data.name.localeCompare(b.data.name))}
function render(){
 $('#total').textContent=records.length;$('#nav-count').textContent=records.length;$('#active').textContent=records.filter(r=>r.data.status==='在职').length;$('#international').textContent=records.filter(r=>r.data.category==='国际学者').length;
 const chosen=$('#department').value;$('#department').innerHTML='<option value="">所有院系</option>'+[...new Set(records.map(r=>r.data.department).filter(Boolean))].sort().map(x=>`<option ${x===chosen?'selected':''}>${esc(x)}</option>`).join('');
 $('#alphabet').innerHTML=['全部',...'ABCDEFGHIJKLMNOPQRSTUVWXYZ','#'].map(x=>`<button class="${letter===x?'selected':''}" data-letter="${x}" aria-pressed="${letter===x}">${x}</button>`).join('');
 const rows=filteredRecords();$('#result-count').textContent=`显示 ${rows.length} 位教授 · 共 ${records.length} 份档案`;
 $('#records').innerHTML=rows.map(r=>{const d=r.data,t=templates.find(t=>t.id===r.template);return `<tr><td><button class="row-link person" data-record="${r.id}"><span class="avatar">${esc(/[^\x00-\x7F]/.test(d.name)?d.name.slice(-2):d.name.split(/\s+/).map(n=>n[0]).slice(0,2).join(''))}</span><span><strong>${esc(d.name)}</strong><small>${esc(d.englishName||d.employeeId||'—')}</small></span></button></td><td class="department-cell">${esc(d.department)}<small>${esc(d.title||'待补充职称')}</small></td><td><span class="tag">${esc(t?.name||r.template)}</span></td><td><span class="status ${['已离职','待入职'].includes(d.status)?'grey':''}">${esc(d.status||'—')}</span></td><td class="muted">${new Date(r.updated_at).toLocaleDateString('zh-CN')}</td><td><button class="icon" data-record="${r.id}" aria-label="打开 ${esc(d.name)} 的档案">›</button></td></tr>`}).join('');$('#empty').hidden=rows.length>0;
}
function templateCards(){return templates.map((t,i)=>`<button class="template-card" data-template="${t.id}" ${!writable()?'disabled':''}><span class="number">0${i+1}</span><div><h3>${t.name}</h3><span class="fine">${t.en}</span></div><p>${t.description}</p><ul>${t.items.map(x=>`<li>${x}</li>`).join('')}</ul><span class="primary" style="padding:8px 13px;border-radius:6px;font-size:14px">使用模板 ↗</span></button>`).join('')}
function setView(view){const isTemplates=view==='templates';$('#directory').hidden=isTemplates;$('#templates-view').hidden=!isTemplates;$('#templates-view').innerHTML='<div class="template-grid">'+templateCards()+'</div>';$('#page-title').textContent=isTemplates?'档案模板':'教授档案';$('#page-subtitle').textContent=isTemplates?'从适合的结构开始，再补充你关心的内容。':'把每一位教授的经历，有条理地保存下来。';document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view))}
function fieldHtml(field,value,prefix='base'){
 const [key,label,type,required,options]=field;const name=prefix+'_'+key;const common=`name="${esc(name)}" ${required?'required':''} ${writable()?'':'disabled'}`;
 let input=type==='textarea'?`<textarea ${common} maxlength="20000">${esc(value)}</textarea>`:type==='select'?`<select ${common}>${['',...(options||[])].map(o=>`<option value="${esc(o)}" ${o===value?'selected':''}>${esc(o||'请选择')}</option>`).join('')}</select>`:`<input ${common} type="${esc(type)}" ${type==='number'?'step="any"':''} value="${esc(value)}" ${type==='text'?'maxlength="500"':''} ${key==='sortName'?'pattern="[A-Za-zÀ-ž].*" placeholder="例如：Zhang Mingyuan / Wilson James"':''}>`;
 return `<label class="${type==='textarea'?'full':''}">${esc(label)}${required?' *':''}${input}${key==='sortName'?'<small>按姓氏在前填写；中文名请填拼音，多音字可自行校正。</small>':''}</label>`;
}
function renderCustom(){const values=new FormData($('#record-form'));for(const f of custom)if(values.has('custom_'+f.id))f.value=values.get('custom_'+f.id);$('#custom-fields').innerHTML=custom.map(f=>`<div class="${f.type==='textarea'?'full':''}">${fieldHtml([f.id,f.label,f.type,false,f.options],f.value,'custom')}${writable()?`<button type="button" data-remove-field="${esc(f.id)}" class="fine" style="margin-top:7px;padding:3px 8px">移除此字段</button>`:''}</div>`).join('')}
async function openRecord(id,templateId){
 editing=id?structuredClone(records.find(r=>r.id===id)):{id:crypto.randomUUID(),template:templateId,version:0,data:{status:'在职',category:templateId==='international'?'国际学者':'本国学者',custom:[]}};
 if(!editing)return;const t=templates.find(t=>t.id===editing.template)||templates[0];custom=structuredClone(editing.data.custom||[]);
 $('#editor-title').textContent=editing.version?editing.data.name+' · 档案':'新建教授档案';$('#editor-template').textContent=t.name+' / '+t.en;$('#form-error').textContent='';
 $('#form-fields').innerHTML='<section class="form-section"><h3>基本信息 / Basic information</h3><div class="form-grid">'+baseFields.map(f=>fieldHtml(f,editing.data[f[0]])).join('')+'</div></section><section class="form-section"><h3>'+esc(t.name)+' / Profile details</h3><div class="form-grid">'+t.extra.map(f=>fieldHtml(f,editing.data[f[0]])).join('')+'</div></section>';
 renderCustom();$('#record-meta').textContent=editing.version?'版本 '+editing.version+' · '+new Date(editing.updated_at).toLocaleString('zh-CN'):'填写必填项后保存';$('#save').hidden=!writable();$('#delete-record').hidden=!writable()||!editing.version;$('#add-field').hidden=!writable();$('#upload-label').hidden=!writable()||!editing.version;$('#attachment-note').textContent=!editing.version?'请先保存档案，再添加附件。':demo?'演示附件仅保留在当前页面。':'附件保存在团队私有存储中，仅授权成员可访问。';$('#attachments').textContent='';loadAttachments.current=[];dirty=false;$('#editor').showModal();if(editing.version)loadAttachments(editing.id).catch(e=>$('#attachment-note').textContent=friendly(e));
}
async function loadAttachments(id){const files=demo?[...(demoFiles.get(id)||[])]:await request('/rest/v1/attachments?select=*&profile_id=eq.'+id+'&order=created_at.asc');if(!editing||editing.id!==id)return;$('#attachments').innerHTML=files.length?files.map(f=>`<div class="attachment"><span>${esc(f.name)} <small class="muted">${(f.size/1024).toFixed(0)} KB</small></span><span class="attachment-actions"><button type="button" data-download="${esc(f.id)}">下载</button>${writable()?`<button type="button" class="delete-attachment" data-delete-attachment="${esc(f.id)}" aria-label="删除附件 ${esc(f.name)}" title="删除附件">✖</button>`:''}</span></div>`).join(''):'<p class="fine">还没有附件。</p>';loadAttachments.current=files}
function readDraft(){const values=new FormData($('#record-form'));const t=templates.find(t=>t.id===editing.template);const data={};for(const f of [...baseFields,...t.extra])data[f[0]]=String(values.get('base_'+f[0])||'').trim();data.custom=custom.map(f=>({...f,value:String(values.get('custom_'+f.id)||'')}));return data}
async function saveRecord(e){e.preventDefault();if(busy||!writable())return;const data=readDraft();if(!data.name||!data.sortName||!data.department){$('#form-error').textContent='请补全姓名、排序名和院系。';return}if(data.startDate&&data.contractEnd&&data.contractEnd<data.startDate){$('#form-error').textContent='聘期结束日期不能早于入职日期。';return}if(data.visitStart&&data.visitEnd&&data.visitEnd<data.visitStart){$('#form-error').textContent='访问结束日期不能早于开始日期。';return}
 busy=true;epoch++;$('#save').disabled=true;$('#save').textContent='正在保存…';$('#form-error').textContent='';
 try{let saved;if(demo){saved={...editing,data,version:editing.version+1,updated_at:new Date().toISOString()};records=[...records.filter(r=>r.id!==saved.id),saved]}else{await ensureSession();const rows=await request('/rest/v1/profiles'+(editing.version?'?id=eq.'+editing.id+'&version=eq.'+editing.version:''),{method:editing.version?'PATCH':'POST',headers:{Prefer:'return=representation'},body:editing.version?{data}:{id:editing.id,template:editing.template,data}});if(!rows?.length)throw Error('另一位成员已经更新了此档案，本次未覆盖。请先复制你的修改，再关闭并同步最新版本。');saved=rows[0];records=[...records.filter(r=>r.id!==saved.id),saved]}
 editing=saved;dirty=false;$('#editor').close();render();toast('档案已保存'+(demo?'（演示）':''));
 }catch(err){$('#form-error').textContent=friendly(err)}finally{busy=false;$('#save').disabled=false;$('#save').textContent='保存档案'}
}
function closeDialog(dialog){if(busy){toast('正在保存或上传，请稍候');return}if(dialog.id==='editor'&&dirty){if(!confirm('有尚未保存的修改，确定关闭并放弃这些修改吗？'))return}dialog.close();if(dialog.id==='editor'){editing=null;dirty=false}}
$('#login-form').addEventListener('submit',async e=>{e.preventDefault();$('#login-error').textContent='';$('#login-submit').disabled=true;try{const form=new FormData(e.target);const data=await request('/auth/v1/token?grant_type=password',{method:'POST',body:{email:form.get('email'),password:form.get('password')},anonymous:true});session={...data,expires_at:Date.now()/1000+data.expires_in};const member=await request('/rest/v1/hr_members?select=role&user_id=eq.'+session.user.id);if(!member.length)throw Error('此账号未获档案访问权限，请联系 HR 管理员。');role=member[0].role;demo=false;e.target.reset();await enter()}catch(err){session=null;$('#workspace').hidden=true;$('#login').hidden=false;$('#login-error').textContent=friendly(err)}finally{$('#login-submit').disabled=false}});
$('#demo').onclick=()=>{demo=true;role='editor';enter()};
$('#logout').onclick=async()=>{if(busy)return;const token=session?.access_token;epoch++;clearInterval(syncTimer);session=null;records=[];demoFiles.clear();demo=false;editing=null;document.querySelectorAll('dialog[open]').forEach(d=>d.close());$('#form-fields').innerHTML='';$('#custom-fields').innerHTML='';$('#attachments').innerHTML='';$('#records').innerHTML='';$('#account-name').textContent='';$('#workspace').hidden=true;$('#login').hidden=false;if(token)request('/auth/v1/logout',{method:'POST',headers:{Authorization:'Bearer '+token}}).catch(()=>toast('本机已退出；云端会话撤销失败，短期令牌到期后失效。'))};
$('#new-record').onclick=()=>{$('#template-options').innerHTML=templateCards();$('#template-dialog').showModal()};
$('#search').addEventListener('input',render);$('#department').onchange=render;$('#status').onchange=render;$('#refresh').onclick=()=>refresh().catch(e=>toast(friendly(e)));$('#clear-filters').onclick=()=>{$('#search').value='';$('#department').value='';$('#status').value='';letter='全部';render()};
$('#record-form').onsubmit=saveRecord;$('#record-form').addEventListener('input',()=>dirty=true);
$('#add-field').onclick=()=>{$('#field-form').reset();$('#field-dialog').showModal()};
$('#field-form').onsubmit=e=>{e.preventDefault();const data=new FormData(e.target),label=String(data.get('label')).trim(),type=data.get('type'),options=String(data.get('options')).split(/[,，]/).map(s=>s.trim()).filter(Boolean);if(!label)return;if(type==='select'&&!options.length){toast('请至少填写一个选项');return}if(custom.some(f=>f.label===label)){toast('已有同名字段，请换一个名称');return}custom.push({id:crypto.randomUUID(),label,type,options,value:''});renderCustom();dirty=true;$('#field-dialog').close()};
$('#attachment-input').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file||!editing?.version||busy)return;if(file.size>10*1024*1024){toast('单个附件不能超过 10 MB');return}if(!['application/pdf','image/png','image/jpeg'].includes(file.type)){toast('仅支持 PDF、PNG、JPEG');return}busy=true;$('#save').disabled=true;let path;try{const id=crypto.randomUUID(),recordId=editing.id;const metadata={id,profile_id:recordId,name:file.name,size:file.size};if(demo){demoFiles.set(recordId,[...(demoFiles.get(recordId)||[]),{...metadata,file}])}else{await ensureSession();path=recordId+'/'+id;await request('/storage/v1/object/faculty-documents/'+path,{method:'POST',body:file,headers:{'Content-Type':file.type,'x-upsert':'false'}});await request('/rest/v1/attachments',{method:'POST',body:{...metadata,path}})}await loadAttachments(recordId);toast('附件已上传')}catch(err){$('#attachment-note').textContent=friendly(err);if(path){$('#attachment-note').textContent+=' 若网络在上传时中断，请同步检查附件；管理员可核查无元数据的存储文件。'}}finally{busy=false;$('#save').disabled=false}};
async function download(id){try{await ensureSession();const file=loadAttachments.current?.find(f=>f.id===id);if(!file)return;const blob=demo?file.file:await request('/storage/v1/object/authenticated/faculty-documents/'+file.path,{blob:true});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=file.name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(err){toast(friendly(err))}}
async function deleteAttachment(id){const file=loadAttachments.current?.find(f=>f.id===id);if(!file||busy||!writable())return;if(!confirm(`确定永久删除附件“${file.name}”吗？此操作无法撤销。`))return;busy=true;try{if(demo){demoFiles.set(editing.id,(demoFiles.get(editing.id)||[]).filter(f=>f.id!==id))}else{await ensureSession();await request('/storage/v1/object/faculty-documents/'+file.path,{method:'DELETE'});await request('/rest/v1/attachments?id=eq.'+id,{method:'DELETE'})}await loadAttachments(editing.id);toast('附件已删除')}catch(err){$('#attachment-note').textContent=friendly(err)}finally{busy=false}}
async function deleteRecord(){if(!editing?.version||busy||!writable())return;const name=editing.data.name||'这份档案';if(!confirm(`确定永久删除“${name}”的整份档案及全部附件吗？此操作无法撤销。`))return;busy=true;$('#delete-record').disabled=true;$('#save').disabled=true;$('#form-error').textContent='';try{if(demo){demoFiles.delete(editing.id);records=records.filter(r=>r.id!==editing.id)}else{await ensureSession();const files=await request('/rest/v1/attachments?select=path&profile_id=eq.'+editing.id);for(const file of files)await request('/storage/v1/object/faculty-documents/'+file.path,{method:'DELETE'});await request('/rest/v1/profiles?id=eq.'+editing.id,{method:'DELETE'})}dirty=false;$('#editor').close();editing=null;render();toast('档案及附件已删除')}catch(err){$('#form-error').textContent=friendly(err)}finally{busy=false;$('#delete-record').disabled=false;$('#save').disabled=false}}
$('#delete-record').onclick=deleteRecord;
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.classList.contains('close'))closeDialog(b.closest('dialog'));if(b.dataset.view)setView(b.dataset.view);if(b.dataset.letter){letter=b.dataset.letter;render()}if(b.dataset.record)openRecord(b.dataset.record);if(b.dataset.template){$('#template-dialog').close();openRecord(null,b.dataset.template)}if(b.dataset.removeField){custom=custom.filter(f=>f.id!==b.dataset.removeField);renderCustom();dirty=true}if(b.dataset.download)download(b.dataset.download);if(b.dataset.deleteAttachment)deleteAttachment(b.dataset.deleteAttachment)});
document.querySelectorAll('dialog').forEach(d=>d.addEventListener('cancel',e=>{e.preventDefault();closeDialog(d)}));
window.addEventListener('beforeunload',e=>{if(dirty||busy){e.preventDefault();e.returnValue=''}});
$('#config-note').textContent=configured?'使用管理员分配的个人账号登录。':'尚未连接团队数据库。你可以先体验演示，正式使用前按部署说明完成接入。';$('#login-submit').disabled=!configured;
// Optional page tools: reuse UI state and permissions; never expose unauthenticated records.
if(document.modelContext?.registerTool){
 const lifecycle=new AbortController();
 const tool={name:'search_faculty_directory',title:'搜索教授目录',description:'在已登录的教授目录内应用姓名搜索；仅返回匹配数量，档案显示在页面。',inputSchema:{type:'object',properties:{query:{type:'string',maxLength:200}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:async input=>{if(!input||typeof input.query!=='string'||input.query.length>200||Object.keys(input).some(k=>k!=='query'))throw Error('query must be a string of at most 200 characters');if(!demo&&!session)throw Error('请先登录');if($('#editor').open)throw Error('请先保存或关闭当前档案');if(!demo)await refresh();setView('all');$('#search').value=input.query;$('#department').value='';$('#status').value='';letter='全部';render();return {count:filteredRecords().length,mode:demo?'demo':'team'}}};
 try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch{}
 window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
}
